#[test]
fn tidying_leaves_a_checkout_with_a_submodule_checked_out_and_says_why() {
    // git will not remove it without force, and the sweep never forces: it
    // used to offer the checkout, have git refuse, and send the person to the
    // log. Nothing in it is work, so "there is work in it" would not be why.
    let scratch = Scratch::new();
    let Some((mut harness, repository, store, tab)) = window_on_a_repository(&scratch) else {
        return;
    };
    add_a_submodule(&repository);
    let checkout = spare_checkout(&mut harness, tab, &store, &[]);
    initialise_the_submodule(&checkout);

    harness.dispatch_worktree(WorktreeAction::OpenMenu(tab));
    harness.wait_for("both checkouts to be read", |harness| {
        harness.worktrees_listed() == Some(2)
    });
    harness.dispatch_worktree(WorktreeAction::AskTidy);
    harness.wait_for("the checkout to be looked in", |harness| {
        harness.worktrees_going().is_some()
    });
    assert_eq!(
        harness.worktrees_going(),
        Some(0),
        "the submodule did not keep it"
    );

    let scene = harness.frame();
    let label = git_in(&checkout, &["rev-parse", "--abbrev-ref", "HEAD"]);
    assert!(
        worktree_menu_reads(&scene, &format!("{label} holds a submodule")),
        "the question does not say why it is left alone"
    );
    assert!(!worktree_menu_says(&scene, "There is work in it"));
}

#[test]
fn stop_spares_the_checkouts_after_the_one_in_flight() {
    // Six checkouts with a build in each is minutes of `git worktree remove`,
    // and the way out of that is a Stop that means it: the one git is
    // deleting finishes — a kill halfway through leaves a checkout neither
    // there nor gone — and nothing after it starts. Pressed before the first
    // has landed, so exactly one goes.
    let scratch = Scratch::new();
    let Some(repository) = scratch_repository(&scratch.path().join("repo")) else {
        eprintln!("skipped: no git here to make a repository with");
        return;
    };
    let store = scratch.path().join("store");

    let mut harness = Harness::seeded();
    harness.workspace_update(|workspace, _| workspace.set_worktrees_directory(store.clone()));
    let tab = harness.active_id();
    let pane = harness.pane_ids()[0];
    harness.update_session(pane, |session| {
        session.working_directory = Some(repository.clone());
    });
    harness.record_git(pane, "main", None);
    harness.frame();

    let mut free: Vec<PathBuf> = Vec::new();
    for _ in 0..3 {
        let made = spare_checkout(&mut harness, tab, &store, &free);
        free.push(made);
    }

    harness.dispatch_worktree(WorktreeAction::OpenMenu(tab));
    harness.wait_for("every checkout to be read", |harness| {
        harness.worktrees_listed() == Some(4)
    });
    harness.dispatch_worktree(WorktreeAction::AskTidy);
    harness.wait_for("the checkouts to be looked in", |harness| {
        harness.worktrees_going() == Some(3)
    });

    harness.dispatch_worktree(WorktreeAction::Tidy);
    // Escape, which is Cancel, which during a sweep is Stop. Dispatched
    // before the queue is pumped, so the first removal has not landed yet
    // whether or not git has finished it.
    harness.dispatch_worktree(WorktreeAction::Cancel);
    assert!(
        harness.worktree_sweep_is_stopping(),
        "Cancel during a sweep walked back to a list that is about to be wrong"
    );
    assert!(
        harness.worktree_menu_is_tidying(),
        "the face was taken down with a removal still in flight"
    );

    harness.wait_for(
        "the sweep to stop and the list to be read again",
        |harness| harness.worktrees_listed().is_some() && !harness.worktree_menu_is_tidying(),
    );
    let left = crate::git::worktree::list(&repository).expect("the repository still lists");
    assert_eq!(
        left.len(),
        3,
        "the stop did not spare the two behind the one in flight: {left:?}"
    );
    assert!(
        !free[0].exists(),
        "the checkout in flight was not let finish"
    );
    assert!(
        free[1].is_dir() && free[2].is_dir(),
        "a checkout after the stop was removed"
    );
    assert!(
        worktree_menu_says(&harness.frame(), "Stopped after 1 of 3"),
        "the list does not say where the sweep stopped"
    );
}

#[test]
fn a_sweep_leaves_standing_a_checkout_a_pane_has_entered_since_it_asked() {
    // A checkout is on the list for having no pane in it when the question
    // was asked, and whatever lock Crook took on it came off as the last pane
    // left. Nothing locks it again when a pane comes back — a reopened tab, a
    // restored session, a shell's `cd` — so git has nothing to refuse over,
    // and the sweep is the one that has to notice: each step asks the panes
    // again, and a checkout one has entered, before the press or while the
    // ones ahead of it were going, is left standing and counted as in use.
    let scratch = Scratch::new();
    let Some(repository) = scratch_repository(&scratch.path().join("repo")) else {
        eprintln!("skipped: no git here to make a repository with");
        return;
    };
    let store = scratch.path().join("store");

    let mut harness = Harness::seeded();
    harness.workspace_update(|workspace, _| workspace.set_worktrees_directory(store.clone()));
    let tab = harness.active_id();
    let pane = harness.pane_ids()[0];
    harness.update_session(pane, |session| {
        session.working_directory = Some(repository.clone());
    });
    harness.record_git(pane, "main", None);
    harness.frame();

    let mut free: Vec<PathBuf> = Vec::new();
    for _ in 0..3 {
        let made = spare_checkout(&mut harness, tab, &store, &free);
        free.push(made);
    }

    // Two panes in the main checkout, to walk into two of the free ones.
    let mut walkers = Vec::new();
    for _ in 0..2 {
        harness.dispatch_action(TabAction::Split(Direction::Right));
        let walker = harness
            .focused_pane_id()
            .expect("the split focused its pane");
        harness.update_session(walker, |session| {
            session.working_directory = Some(repository.clone());
        });
        walkers.push(walker);
    }

    harness.dispatch_worktree(WorktreeAction::OpenMenu(tab));
    harness.wait_for("every checkout to be read", |harness| {
        harness.worktrees_listed() == Some(4)
    });
    harness.dispatch_worktree(WorktreeAction::AskTidy);
    harness.wait_for("the checkouts to be looked in", |harness| {
        harness.worktrees_going() == Some(3)
    });
    let going: Vec<PathBuf> =
        harness.workspace.read(&harness.app, |workspace, _| {
            match &workspace.tab_menu().sweep {
                super::tab_menu::Sweep::Ready { going, .. } => {
                    going.iter().map(|going| going.path.clone()).collect()
                }
                _ => Vec::new(),
            }
        });

    // One walks into the first after the question and before the press.
    harness.update_session(walkers[0], |session| {
        session.working_directory = Some(going[0].clone());
    });
    harness.dispatch_worktree(WorktreeAction::Tidy);
    // And one into the last while the second is going: before the queue is
    // pumped, so that removal has not landed yet.
    harness.update_session(walkers[1], |session| {
        session.working_directory = Some(going[2].clone());
    });

    harness.wait_for(
        "the sweep to finish and the list to be read again",
        |harness| !harness.worktree_menu_is_tidying() && !harness.worktree_menu_is_busy(),
    );
    assert!(
        going[0].is_dir(),
        "the checkout a pane entered before the press was removed from under it"
    );
    assert!(
        going[2].is_dir(),
        "the checkout a pane entered during the sweep was removed from under it"
    );
    assert!(
        !going[1].exists(),
        "the checkout nobody entered was not removed"
    );
    assert_eq!(
        harness.worktrees_listed(),
        Some(3),
        "git does not list exactly the main checkout and the two kept"
    );
    assert_eq!(
        harness.worktree_problem().as_deref(),
        Some("2 checkouts are in use now and were kept."),
        "the list does not say why two of the three are still there"
    );
}

/// Runs git in `directory` for a test that has to make history the menu then
/// reads, and says what failed when it does.
fn git_in(directory: &Path, args: &[&str]) -> String {
    let output = crate::process::command("git")
        .args(["-c", "commit.gpgsign=false"])
        .args(args)
        .current_dir(directory)
        .stdin(std::process::Stdio::null())
        .output()
        .expect("git is installed; the repository was made with it");
    assert!(
        output.status.success(),
        "git {args:?} failed: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    String::from_utf8_lossy(&output.stdout).trim().to_owned()
}

#[test]
fn a_checkout_whose_work_landed_is_marked_merged_and_swept_on_its_own() {
    // Two finished-looking checkouts, one whose work the base has as a squash
    // and one whose work it does not. git calls both branches unmerged; the
    // menu has to tell them apart, say so on the rows, and offer to take the
    // first without the second.
    let scratch = Scratch::new();
    let Some(repository) = scratch_repository(&scratch.path().join("repo")) else {
        eprintln!("skipped: no git here to make a repository with");
        return;
    };
    let store = scratch.path().join("store");

    let mut harness = Harness::seeded();
    harness.workspace_update(|workspace, _| workspace.set_worktrees_directory(store.clone()));
    let tab = harness.active_id();
    let pane = harness.pane_ids()[0];
    harness.update_session(pane, |session| {
        session.working_directory = Some(repository.clone());
    });
    harness.record_git(pane, "main", None);
    harness.frame();

    let landed = spare_checkout(&mut harness, tab, &store, &[]);
    let open = spare_checkout(&mut harness, tab, &store, std::slice::from_ref(&landed));
    let branch = |checkout: &Path| git_in(checkout, &["rev-parse", "--abbrev-ref", "HEAD"]);
    let (landed_branch, open_branch) = (branch(&landed), branch(&open));

    fs::write(landed.join("landed.txt"), "finished\n").expect("the checkout is there");
    git_in(&landed, &["add", "landed.txt"]);
    git_in(&landed, &["commit", "--no-verify", "-m", "finished"]);
    fs::write(open.join("open.txt"), "not yet\n").expect("the checkout is there");
    git_in(&open, &["add", "open.txt"]);
    git_in(&open, &["commit", "--no-verify", "-m", "not yet"]);
    // What the forge's squash button does, on the branch the repository was
    // made on — which is the base, whatever this machine calls it.
    git_in(&repository, &["merge", "--squash", &landed_branch]);
    git_in(
        &repository,
        &["commit", "--no-verify", "-m", "finished, squashed"],
    );

    harness.dispatch_worktree(WorktreeAction::OpenMenu(tab));
    harness.wait_for("the proof to come back", |harness| {
        harness.worktrees_landed().is_some()
    });
    assert_eq!(
        harness.worktrees_landed(),
        Some(vec![landed_branch.clone()]),
        "the squashed branch was not the one proved"
    );
    let scene = harness.frame();
    let row_says = |branch: &str| {
        let row = worktree_row_saying(&scene, branch);
        text_where(&scene, |position| row.contains_point(position))
    };
    assert!(
        row_says(&landed_branch).contains("merged"),
        "the row whose work landed is not marked: {:?}",
        row_says(&landed_branch)
    );
    assert!(
        !row_says(&open_branch).contains("merged"),
        "the row with open work is marked as though it had landed"
    );
    assert!(
        worktree_menu_says(&scene, "Remove 2 free checkouts"),
        "the broader sweep stopped offering both"
    );
    assert!(
        worktree_menu_says(&scene, "Remove 1 merged checkout"),
        "the list did not offer the one checkout whose work landed"
    );

    harness.dispatch_worktree(WorktreeAction::AskTidyLanded);
    assert_eq!(harness.worktrees_swept(), Some((0, 1)));
    harness.wait_for("the checkout to be looked in", |harness| {
        harness.worktrees_going().is_some()
    });
    assert_eq!(harness.worktrees_going(), Some(1));
    harness.dispatch_worktree(WorktreeAction::Tidy);
    harness.wait_for("the list to be read again", |harness| {
        harness.worktrees_listed() == Some(2) && !harness.worktree_menu_is_tidying()
    });

    assert!(
        !landed.exists(),
        "the checkout whose work landed is still there"
    );
    assert!(open.is_dir(), "the checkout with open work was taken too");
    // The branch is the work, landed or not, and nothing here deletes one.
    let branches = crate::git::worktree::branches(&repository).expect("the repository lists");
    assert!(
        branches.contains(&landed_branch) && branches.contains(&open_branch),
        "a branch went with its checkout: {branches:?}"
    );
}

#[test]
fn removing_the_last_checkout_leaves_no_empty_directory_in_the_store() {
    // git deletes the checkout and nothing above it, so the store kept a
    // directory per repository for ever after its last checkout went.
    let scratch = Scratch::new();
    let Some(repository) = scratch_repository(&scratch.path().join("repo")) else {
        eprintln!("skipped: no git here to make a repository with");
        return;
    };
    let store = scratch.path().join("store");

    let mut harness = Harness::seeded();
    harness.workspace_update(|workspace, _| workspace.set_worktrees_directory(store.clone()));
    let tab = harness.active_id();
    let pane = harness.pane_ids()[0];
    harness.update_session(pane, |session| {
        session.working_directory = Some(repository.clone());
    });
    harness.record_git(pane, "main", None);
    harness.frame();

    let made = spare_checkout(&mut harness, tab, &store, &[]);
    let holder = made
        .parent()
        .expect("a checkout sits in a directory of the store")
        .to_path_buf();
    assert_ne!(holder, store, "the checkout is not grouped by repository");

    harness.dispatch_worktree(WorktreeAction::OpenMenu(tab));
    harness.wait_for("both checkouts to be read", |harness| {
        harness.worktrees_listed() == Some(2)
    });
    let index = harness
        .worktree_index_under(&store)
        .expect("the checkout that was made is not in the menu");
    harness.dispatch_worktree(WorktreeAction::AskRemove(index));
    harness.dispatch_worktree(WorktreeAction::Remove { force: false });
    harness.wait_for("the list to be read again", |harness| {
        harness.worktrees_listed() == Some(1)
    });

    assert!(!made.exists(), "the checkout was not removed");
    assert!(
        !holder.exists(),
        "{} was left behind with nothing in it",
        holder.display()
    );
    assert!(store.is_dir(), "the store itself went with it");
}

